import{f as n,J as i,o as a,c as o,a6 as t,b as r,w as s,a as l,K as h,a7 as c}from"./chunks/framework.Dd1qhYRL.js";const w=JSON.parse('{"title":"Changes","description":"","frontmatter":{},"headers":[],"relativePath":"guide/changes/overview.md","filePath":"guide/changes/overview.md"}'),p={name:"guide/changes/overview.md"};function g(b,e,f,u,m,k){const d=i("Mermaid");return a(),o("div",null,[e[1]||(e[1]=t(`<h1 id="changes" tabindex="-1">Changes <a class="header-anchor" href="#changes" aria-label="Permalink to “Changes”">​</a></h1><p>A change takes a database that already exists to the schema in <code>db/sql/</code>. noorm runs each change once per database and records the result.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> change</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> order-status</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Created: 2026-10-20-order-status</span></span>
<span class="line"><span>  /home/dana/orders/db/changes/2026-10-20-order-status</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>db/changes/2026-10-20-order-status/</span></span>
<span class="line"><span>├── change/</span></span>
<span class="line"><span>│   └── 001_order-status.sql</span></span>
<span class="line"><span>├── revert/</span></span>
<span class="line"><span>│   └── 001_order-status.sql</span></span>
<span class="line"><span>└── changelog.md</span></span></code></pre></div><p>Each <code>.sql</code> file starts as one comment line. Replace it with SQL, as <a href="/guide/changes/add-a-column.html">Add a column</a> does for this change. In the TUI, press <code>g</code> from home, then <code>a</code>.</p><h2 id="what-is-in-a-change-folder" tabindex="-1">What is in a change folder? <a class="header-anchor" href="#what-is-in-a-change-folder" aria-label="Permalink to “What is in a change folder?”">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Holds</th><th>Read by</th></tr></thead><tbody><tr><td><code>change/</code></td><td>forward scripts</td><td><code>change run</code>, <code>ff</code>, <code>next</code></td></tr><tr><td><code>revert/</code></td><td>rollback scripts</td><td><code>change revert</code>, <code>rewind</code></td></tr><tr><td><code>changelog.md</code></td><td>why the change exists</td><td>people. noorm records only that it exists</td></tr></tbody></table><p>Files in <code>change/</code> and <code>revert/</code> run by extension:</p><table tabindex="0"><thead><tr><th>Extension</th><th>Runs</th></tr></thead><tbody><tr><td><code>.sql</code></td><td>as written</td></tr><tr><td><code>.sql.tmpl</code></td><td>after Eta renders it (<a href="/guide/sql-files/templates.html">Templates</a>)</td></tr><tr><td><code>.txt</code></td><td>a manifest: files from <code>db/sql/</code>, in place</td></tr></tbody></table><p>Other files are not run, though a template still reads the data files beside it. A folder with neither <code>change/</code> nor <code>revert/</code> is not a change, so shared fragments and archives can sit beside the real ones.</p><h2 id="how-are-changes-and-files-ordered" tabindex="-1">How are changes and files ordered? <a class="header-anchor" href="#how-are-changes-and-files-ordered" aria-label="Permalink to “How are changes and files ordered?”">​</a></h2><p>noorm sorts by name at both levels, so the name is the order.</p><table tabindex="0"><thead><tr><th>Level</th><th>Pattern</th><th>Example</th></tr></thead><tbody><tr><td>Change folder</td><td><code>YYYY-MM-DD-slug</code></td><td><code>2026-10-20-order-status</code></td></tr><tr><td>File</td><td><code>NNN_slug.ext</code></td><td><code>001_order-status.sql</code></td></tr></tbody></table><ul><li><code>change add</code> builds the folder name from today&#39;s date and a slug of your description.</li><li>Pad file numbers to three digits. Names sort as text, so <code>10_</code> comes before <code>9_</code>.</li><li><code>revert/</code> runs in the same filename order as <code>change/</code>. Number its files in the order the undo has to happen.</li></ul><p><code>invoice_line</code> references <code>invoice</code>, so the revert drops the child first:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>change/                       revert/</span></span>
<span class="line"><span>├── 001_invoice.sql           ├── 001_invoice-line.sql</span></span>
<span class="line"><span>└── 002_invoice-line.sql      └── 002_invoice.sql</span></span></code></pre></div><h2 id="how-does-a-change-reuse-a-view-or-function-from-db-sql" tabindex="-1">How does a change reuse a view or function from db/sql/? <a class="header-anchor" href="#how-does-a-change-reuse-a-view-or-function-from-db-sql" aria-label="Permalink to “How does a change reuse a view or function from db/sql/?”">​</a></h2><p>A <code>.txt</code> manifest lists files in <code>db/sql/</code>. noorm runs them in place, so the view is defined once and the change never copies its SQL:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># db/changes/2026-10-22-open-orders/change/001_rebuild-views.txt</span></span>
<span class="line"><span>02_views/01_open_orders.sql</span></span>
<span class="line"><span>02_views/02_unpaid_invoices.sql</span></span></code></pre></div><p>A manifest sorts among the other files of its folder. Use that to drop a dependent view, alter the table, then rebuild the view:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>change/</span></span>
<span class="line"><span>├── 001_drop-unpaid-invoices.sql  -- DROP VIEW IF EXISTS unpaid_invoices;</span></span>
<span class="line"><span>├── 002_widen-amount.sql          -- ALTER TABLE invoice_line ALTER COLUMN amount TYPE numeric(14,2);</span></span>
<span class="line"><span>└── 003_rebuild-views.txt         02_views/02_unpaid_invoices.sql</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Rule</th><th>Detail</th></tr></thead><tbody><tr><td>Paths</td><td>one per line, relative to <code>paths.sql</code>: <code>02_views/01_open_orders.sql</code>, not <code>db/sql/02_views/...</code></td></tr><tr><td>Ignored lines</td><td>blank lines and lines starting with <code>#</code></td></tr><tr><td>Order</td><td>lines run in file order. A path listed twice in one change runs once, at its first position</td></tr><tr><td>Content</td><td>the file as it is at run time, not as it was when you wrote the change</td></tr><tr><td>Revert</td><td>a manifest in <code>revert/</code> rebuilds the current definition. To restore an older one, write its <code>CREATE OR REPLACE</code> inline</td></tr></tbody></table><p>A manifest is resolved every time noorm reads the change, so one missing path makes the whole change unreadable:</p>`,24)),(a(),r(c,null,{default:s(()=>[h(d,{id:"mermaid-243",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20M%5B%22001_rebuild-views.txt%22%5D%20--%3E%20E%7B%22every%20listed%20path%3Cbr%2F%3Eexists%20in%20db%2Fsql%2F%3F%22%7D%0A%20%20%20%20E%20--%3E%7Cyes%7C%20R%5B%22runs%20each%20file's%3Cbr%2F%3Ecurrent%20content%22%5D%0A%20%20%20%20E%20--%3E%7Cno%7C%20U%5B%22change%20is%20unreadable%22%5D%0A%20%20%20%20U%20--%3E%20L%5B%22change%20list%20shows%3Cbr%2F%3Efailed%20with%20the%20path%22%5D%0A%20%20%20%20U%20--%3E%20F%5B%22ff%20and%20next%20stop%20here%3Cbr%2F%3Eunless%20it%20already%20ran%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t(`<p><a href="/guide/changes/forward-revert.html#what-happens-when-a-change-folder-cannot-be-read">Forward and revert</a> covers what <code>ff</code> does with it. An empty manifest, or one with only comments, is unreadable too.</p><h2 id="how-do-i-see-what-is-pending" tabindex="-1">How do I see what is pending? <a class="header-anchor" href="#how-do-i-see-what-is-pending" aria-label="Permalink to “How do I see what is pending?”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> change</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2026-10-19-sales-order (success)</span></span>
<span class="line"><span>2026-10-20-order-status (reverted)</span></span>
<span class="line"><span>2026-10-21-invoice (failed): 002_invoice-line.sql: [Err 1] near &quot;(&quot;: syntax error</span></span>
<span class="line"><span>2026-10-23-payment (pending)</span></span>
<span class="line"><span>1 pending change(s)</span></span></code></pre></div><p>Each line is <code>name (status)</code>. A change recorded in the database whose folder is gone shows <code>(status, orphaned)</code>. <code>--json</code> adds <code>appliedAt</code>, <code>appliedBy</code>, <code>revertedAt</code>, <code>errorMessage</code>, <code>isNew</code>, and <code>orphaned</code> to each entry. <a href="/guide/changes/forward-revert.html#which-statuses-can-a-change-have">Forward and revert</a> defines the five statuses.</p><h2 id="what-bites" tabindex="-1">What bites <a class="header-anchor" href="#what-bites" aria-label="Permalink to “What bites”">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>change run</code> fails: files are empty or contain only template placeholders</td><td>The scaffolded stub is a comment, and a change needs real SQL</td><td>Replace the comment with SQL</td></tr><tr><td>A folder in <code>db/changes/</code> never appears in <code>change list</code></td><td>It has neither <code>change/</code> nor <code>revert/</code></td><td>Add <code>change/</code> with at least one file</td></tr><tr><td><code>change list</code> shows <code>failed</code> with <code>references missing file</code></td><td>A manifest names a file that <code>db/sql/</code> no longer has. Deleting or renaming a <code>db/sql/</code> file breaks every unapplied change that lists it</td><td>Restore the file, or fix the manifest line</td></tr><tr><td>You edited an applied change and <code>change ff</code> does nothing</td><td><code>ff</code> skips applied changes, so databases that ran it keep the old body</td><td>Add a new change. <code>change run &lt;name&gt;</code> re-executes the edit on the one database you point it at</td></tr><tr><td><code>change ff</code> fails on a database built from <code>db/sql/</code></td><td>A build records no changes, so <code>ff</code> replays all of them</td><td>Write each statement to be safe to run twice (<a href="/guide/changes/add-a-column.html">Add a column</a>)</td></tr><tr><td>A manifest-listed table file fails on replay: already exists</td><td>A manifest runs the file&#39;s current content, and <code>CREATE TABLE</code> fails on an existing table</td><td>List only <code>CREATE OR REPLACE</code> objects: views, functions, procedures, triggers</td></tr><tr><td><code>1 pending change(s)</code> is fewer than <code>ff</code> will run</td><td>The footer counts <code>pending</code> only. <code>ff</code> also runs <code>reverted</code> and <code>stale</code></td><td>Read each status in the list</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/guide/changes/forward-revert.html">Forward and revert</a>: apply and roll back</li><li><a href="/guide/changes/history.html">History</a>: what each run recorded</li><li><a href="/guide/changes/add-a-column.html">Add a column</a>: one edit, both folders</li><li><a href="/guide/sql-files/templates.html">Templates</a>: <code>.sql.tmpl</code> files in changes</li></ul>`,9))])}const y=n(p,[["render",g]]);export{w as __pageData,y as default};
